-- 1. Enable btree_gist extension to allow scalar + range operator combinations
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- 2. Create table with exclusion constraint
CREATE TABLE meeting_room_reservations (
    id SERIAL PRIMARY KEY,
    room_id INT NOT NULL,
    booking_slot TSTZRANGE NOT NULL,
    -- Room IDs must be equal (=) AND booking slots must NOT overlap (&&)
    EXCLUDE USING gist (
        room_id WITH =,
        booking_slot WITH &&
    )
);

CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE meeting_room_reservations (
    id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    room_id   INT NOT NULL,
    slot      TSTZRANGE NOT NULL,
    attendees INT NOT NULL,
    CONSTRAINT room_slot_no_overlap
        EXCLUDE USING gist (room_id WITH =, slot WITH &&),
    CONSTRAINT slot_not_empty CHECK (NOT isempty(slot)),
    CONSTRAINT slot_is_bounded CHECK (lower_inc(slot) AND NOT upper_inc(slot))
);

INSERT INTO meeting_room_reservations (room_id, slot, attendees)
VALUES (1, '[2026-05-01 09:00+00, 2026-05-01 10:00+00)', 4);

