-- ERROR: conflicting key value violates exclusion constraint "room_slot_no_overlap"

-- The conflicting row is reported in the error DETAIL.
-- Inspect the constraint definition:
SELECT conname, pg_get_constraintdef(oid) FROM pg_constraint
WHERE conname = 'room_slot_no_overlap';

ALTER TABLE meeting_room_reservations
  DROP CONSTRAINT room_slot_no_overlap,
  ADD CONSTRAINT room_slot_no_overlap
      EXCLUDE USING gist (room_id WITH =, slot WITH &&) DEFERRABLE INITIALLY IMMEDIATE;

BEGIN;
SET CONSTRAINTS room_slot_no_overlap DEFERRED;
UPDATE meeting_room_reservations SET slot = '[2026-05-01 10:00+00, 2026-05-01 11:00+00)' WHERE id = 1;
COMMIT;   -- validated once, at commit
